effect.shader:
mat2 rot2m(float a){
float s = sin(a);
float c = cos(a);
return mat2(c, -s, s, c);
}
vec2 l2s( vec2 v ) {
return (vec4(v,0.,1.)*acLayerToScreen).xy;
}
vec3 mod289(vec3 x) {
return x - floor(x * (1.0 / 289.0)) * 289.0;
}
vec2 mod289(vec2 x) {
return x - floor(x * (1.0 / 289.0)) * 289.0;
}
vec3 permute(vec3 x) {
return mod289(((x*34.0)+1.0)*x);
}
float snoise(vec2 v)
{
const vec4 C = vec4(0.211324865405187,
0.366025403784439,
-0.577350269189626,
0.024390243902439);
vec2 i  = floor(v + dot(v, C.yy) );
vec2 x0 = v -   i + dot(i, C.xx);
vec2 i1;
i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
vec4 x12 = x0.xyxy + C.xxzz;
x12.xy -= i1;
i = mod289(i);
vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
+ i.x + vec3(0.0, i1.x, 1.0 ));
vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
m = m*m ;
m = m*m ;
vec3 x = 2.0 * fract(p * C.www) - 1.0;
vec3 h = abs(x) - 0.5;
vec3 ox = floor(x + 0.5);
vec3 a0 = x - ox;
m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
vec3 g;
g.x  = a0.x  * x0.x  + h.x  * x0.y;
g.yz = a0.yz * x12.xz + h.yz * x12.yw;
return 130.0 * dot(m, g);
}
float staticV(vec2 syamjaidtz) {
float staticHeight = snoise(vec2(9.0,1.0*1.2+3.0))*0.3+5.0;
float staticAmount = snoise(vec2(1.0,1.0*1.2-6.0))*0.1+0.3;
float staticStrength = snoise(vec2(-9.75,1.0*0.6-3.0))*2.0+2.0;
return (1.0-step(snoise(vec2(5.0*pow(1.0,2.0)+pow(syamjaidtz.x*7.0,1.2),pow((mod(1.0,100.0)+100.0)*syamjaidtz.y*0.3+3.0,staticHeight))),staticAmount))*staticStrength;
}
void main ()
{
vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
vec2 syamjaidtz = acScreenNorm;
syamjaidtz -= 0.5;
syamjaidtz.x *= acScreenSize.x/acScreenSize.y;
syamjaidtz /= 1.0;
syamjaidtz.x /= acScreenSize.x/acScreenSize.y;
syamjaidtz += 0.5;
float rad = 0.0 * 0.0174533;
vec2 v = normalize(vec2(cos(rad),-sin(rad)));
vec4 result;
float jerkOffset = (1.0-step(snoise(vec2(1.0*1.3,5.0)),0.8))*0.05;
float fuzzOffset = snoise(vec2(seed*15.0,syamjaidtz.y*80.0))*0.1;
float largeFuzzOffset = snoise(vec2(wave*1.0,syamjaidtz.y*25.0))*ggg;
float vertMovementOn = (1.0-step(snoise(vec2(1.0*0.2,8.0)),0.4))*1.0;
float vertJerk = (1.0-step(snoise(vec2(1.0*1.5,5.0)),0.6))*1.0;
float vertJerk2 = (1.0-step(snoise(vec2(1.0*5.5,5.0)),0.2))*1.0;
float yOffset = abs(sin(1.0)*4.0)*vertMovementOn+vertJerk*vertJerk2*0.3;
float y = mod(syamjaidtz.y+yOffset,hardoff);
float xOffset = (fuzzOffset + largeFuzzOffset) * horzFuzzOpt;
float staticVal = 0.0;
for (float y = -1.0; y <= 1.0; y += 1.0) {
float maxDist = 5.0/200.0;
float dist = y/200.0;
staticVal += staticV(vec2(syamjaidtz.x,syamjaidtz.y+dist))*(maxDist-abs(dist))*1.7;
}
staticVal *= bottomStaticOpt;
float red 	=   texture2DCv(	inputImg.texture, 	vec2(syamjaidtz.x + xOffset -0.01*rgbOffsetOpt,y)).r+staticVal;
float green = 	texture2DCv(	inputImg.texture, 	vec2(syamjaidtz.x + xOffset,	  y)).g+staticVal;
float blue 	=	texture2DCv(	inputImg.texture, 	vec2(syamjaidtz.x + xOffset +0.01*rgbOffsetOpt,y)).b+staticVal;
vec3 color = vec3(red,green,blue);
float scanline = sin(syamjaidtz.y*scalinesOptb)*scalinesOpta*scalinesOpt;
color -= scanline;
result = vec4(color,1.0);
vec4 texColorOri = texture2DCv(inputImg.texture,acScreenNorm);
vec4 final = result * texColor.a;
gl_FragColor = mix(texColor,final,alpha);
}
